export function downloadsFor(locale){
  const normalized=['en','pl','de'].includes(locale)?locale:'en';
  return {copy:downloadCopy[normalized],items:acmeDownloads};
}

export const pageSections={en,pl,de};

export function sectionsFor(locale,route){
  const normalized=['en','pl','de'].includes(locale)?locale:'en';
  return pageSections[normalized][route]??pageSections.en[route]??null;
}
